import net.dawson.adorablehamsterpets.AdorableHamsterPets;

public class RemoteLinkManager {
    public static final RemoteLinkManager INSTANCE = new RemoteLinkManager();
    private static final Gson GSON = new Gson();
    private static final String REMOTE_URL = "https://raw.githubusercontent.com/DawsonBodenhamer/AdorableHamsterPets-Source/develop/links/links.json";
    private Map<String, String> links = Collections.emptyMap();
    private boolean initialized = false;
    private Path cacheFilePath;
    private HttpClient httpClient;

    private RemoteLinkManager() {
    }

    public void refreshLinksOnce() {
        if (!this.initialized) {
            this.initialize();
            this.initialized = true;
        }
        HttpRequest request = HttpRequest.newBuilder().uri(URI.create(REMOTE_URL)).GET().build();
        ((CompletableFuture)this.httpClient.sendAsync(request, HttpResponse.BodyHandlers.ofString()).thenAccept(response -> {
            if (response.statusCode() == 200) {
                Type type = new TypeToken<Map<String, String>>(){}.getType();
                Map newLinks = (Map)GSON.fromJson((String)response.body(), type);
                if (newLinks != null) {
                    this.links = newLinks;
                    this.saveCache();
                    AdorableHamsterPets.LOGGER.info("[RemoteLinks] Successfully refreshed remote links.");
                }
            } else {
                AdorableHamsterPets.LOGGER.warn("[RemoteLinks] Failed to fetch links from remote (Status {}).", (Object)response.statusCode());
            }
        })).exceptionally(e -> {
            AdorableHamsterPets.LOGGER.warn("[RemoteLinks] Exception while fetching links from remote: {}. Using cached data if available.", (Object)e.toString());
            return null;
        });
    }

