final class ParticleAnimationUtil {
    private static final int SPAWN_ANIMATION_TICKS = 20;
    private static final int FADE_IN_TICKS = 10;
    private static final float SPAWN_OVERSHOOT = 0.001f;
    private static final float MIN_START_SCALE = 0.8f;
    private static final float SETTLE_START = 0.02f;
    private static final float SETTLE_SPAN = 0.38f;

    static float growInScale(int age) {
        float progress = Mth.m_14036_((float)((float)age / 20.0f), (float)0.0f, (float)1.0f);
        float minimumStartScale = Mth.m_14036_((float)0.8f, (float)0.0f, (float)1.0f);
        if (progress <= 0.0f) {
            return minimumStartScale;
        }
        if (progress >= 1.0f) {
            return 1.0f;
        }
        float easedProgress = ParticleAnimationUtil.exponentialEaseInOut(progress);
        float settleProgress = Mth.m_14036_((float)((progress - 0.02f) / 0.38f), (float)0.0f, (float)1.0f);
        float overshoot = 0.001f * (float)Math.sin((double)settleProgress * Math.PI) * (float)Math.exp(-1.6 * (double)settleProgress);
        float animatedScale = Math.max(0.0f, easedProgress + overshoot);
        return minimumStartScale + (1.0f - minimumStartScale) * animatedScale;
    }

    static float interpolateScale(float previousScale, float currentScale, float tickDelta) {
        float clampedTickDelta = Mth.m_14036_((float)tickDelta, (float)0.0f, (float)1.0f);
        return Mth.m_14179_((float)clampedTickDelta, (float)previousScale, (float)currentScale);
    }

    static float fadeInOpacity(int age) {
        return Mth.m_14036_((float)((float)age / 10.0f), (float)0.0f, (float)1.0f);
    }

    private static float exponentialEaseInOut(float progress) {
        if (progress <= 0.0f || progress >= 1.0f) {
            return progress;
        }
        return progress < 0.5f ? 0.5f * (float)Math.exp(20.0 * (double)progress - 10.0) : 1.0f - 0.5f * (float)Math.exp(-20.0 * (double)progress + 10.0);
    }

    private ParticleAnimationUtil() {
    }
}

