import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.file.Files;
import java.nio.file.LinkOption;
import java.nio.file.Path;
import java.nio.file.attribute.FileAttribute;
import java.util.Collections;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CompletableFuture;
import net.dawson.adorablehamsterpets.AdorableHamsterPets;

public class PlayerPerkManager {
    public static final PlayerPerkManager INSTANCE = new PlayerPerkManager();
    private static final Gson GSON = new Gson();
    private static final String REMOTE_URL = "https://raw.githubusercontent.com/DawsonBodenhamer/AdorableHamsterPets-Source/develop/perks/perks.json";
    private Map<String, Set<String>> perks = Collections.emptyMap();
    private boolean initialized = false;
    private Path cacheFilePath;
    private HttpClient httpClient;

    private PlayerPerkManager() {
    }

    public void refreshManifestOnce() {
        if (!this.initialized) {
            this.initialize();
            this.initialized = true;
        }
        HttpRequest request = HttpRequest.newBuilder().uri(URI.create(REMOTE_URL)).GET().build();
        ((CompletableFuture)this.httpClient.sendAsync(request, HttpResponse.BodyHandlers.ofString()).thenAccept(response -> {
            if (response.statusCode() == 200) {
                Type type = new TypeToken<Map<String, Set<String>>>(){}.getType();
                Map newPerks = (Map)GSON.fromJson((String)response.body(), type);
                if (newPerks != null) {
                    this.perks = newPerks;
                    this.saveCache();
                    AdorableHamsterPets.LOGGER.info("[Perks] Successfully refreshed player perks.");
                }
            } else {
                AdorableHamsterPets.LOGGER.warn("[Perks] Failed to fetch perks from remote (Status {}).", (Object)response.statusCode());
            }
        })).exceptionally(e -> {
            AdorableHamsterPets.LOGGER.warn("[Perks] Exception while fetching perks from remote: {}. Using cached data if available.", (Object)e.toString());
            return null;
        });
    }

